function normalizeLocale(value) {
  var raw = String(value || "").trim().toLowerCase().replace(/-/g, "_")
  return raw === "ru" || raw.indexOf("ru_") === 0 ? "ru" : "en"
}

function boundedValue(value) {
  return String(value === undefined || value === null ? "" : value)
    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, " ")
    .substring(0, MAX_VALUE_LENGTH)
}

function translate(key, locale, values) {
  var stableKey = String(key || "").substring(0, 96)
  var entry = CATALOG[stableKey]
  if (!entry || typeof entry.en !== "string" || entry.en === "")
    return ("Missing translation: " + (stableKey || "unknown")).substring(0, MAX_TEXT_LENGTH)
  var selected = normalizeLocale(locale)
  var text = typeof entry[selected] === "string" && entry[selected] !== ""
    ? entry[selected] : entry.en
  var data = values && typeof values === "object" ? values : {}
  text = text.replace(/\{([A-Za-z][A-Za-z0-9_]*)\}/g, function(match, name) {
    return Object.prototype.hasOwnProperty.call(data, name) ? boundedValue(data[name]) : match
  })
  return text.substring(0, MAX_TEXT_LENGTH)
}

// A semantic code may outlive the message that originally set it while
// asynchronous QML operations finish. Localize it only when the current safe
// English fallback is the catalog fallback for that exact code; otherwise the
// newer message must win.
function publicErrorKey(code, fallback) {
  var stableCode = String(code || "").substring(0, 64)
  var key = "error." + stableCode
  var entry = CATALOG[key]
  return entry && typeof entry.en === "string" && String(fallback || "") === entry.en
    ? key : ""
}

function importReasons(value, locale) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return ""
  var keys = ["unsupported_field", "unsupported_transport", "unsupported_option", "invalid_profile", "unsupported_protocol", "duplicate"]
  var lines = []
  keys.forEach(function(key) {
    var count = value[key]
    if (typeof count === "number" && isFinite(count) && Math.floor(count) === count && count > 0 && count <= 65536)
      lines.push(translate("import.reason." + key, locale) + ": " + count)
  })
  return lines.join("\n").substring(0, MAX_TEXT_LENGTH)
}

function importSummary(value, locale) {
  if (!value) return ""
  var counts = translate("import.summary", locale, value)
  var reasons = importReasons(value.skipReasons, locale)
  return counts + (reasons ? "\n" + reasons : "")
}

function plural(baseKey, count, locale) {
  var amount = Math.max(0, Math.floor(Number(count) || 0))
  var selected = normalizeLocale(locale)
  var form = amount === 1 ? "one" : "many"
  if (selected === "ru") {
    var mod10 = amount % 10
    var mod100 = amount % 100
    if (mod10 === 1 && mod100 !== 11) form = "one"
    else if (mod10 >= 2 && mod10 <= 4 && !(mod100 >= 12 && mod100 <= 14)) form = "few"
  }
  return amount + " " + translate("count." + baseKey + "." + form, selected)
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    CATALOG: CATALOG,
    MAX_TEXT_LENGTH: MAX_TEXT_LENGTH,
    MAX_VALUE_LENGTH: MAX_VALUE_LENGTH,
    normalizeLocale: normalizeLocale,
    boundedValue: boundedValue,
    translate: translate,
    publicErrorKey: publicErrorKey,
    importReasons: importReasons,
    importSummary: importSummary,
    plural: plural
  }
}
